import{_ as a,o as e,c as t,a4 as n}from"./chunks/framework.BaMAT_0D.js";const v=JSON.parse('{"title":"知识图谱 · Course Map","description":"浙江大学计算机科学与技术专业课程脉络与知识图谱全局导览","frontmatter":{"title":"知识图谱 · Course Map","description":"浙江大学计算机科学与技术专业课程脉络与知识图谱全局导览"},"headers":[],"relativePath":"Guide/logic.md","filePath":"Guide/logic.md","lastUpdated":1793365822000}'),i={name:"Guide/logic.md"};function l(c,s,o,d,p,r){return e(),t("div",null,[...s[0]||(s[0]=[n('<h1 id="知识图谱-·-course-map" tabindex="-1">知识图谱 · Course Map <a class="header-anchor" href="#知识图谱-·-course-map" aria-label="Permalink to &quot;知识图谱 · Course Map&quot;">​</a></h1><div class="garden-badge">🧭 体系化视野 · 浙江大学计算机科学专业培养逻辑</div><p>Welcome to <strong>My Note</strong>,浙大计科学子与技术探索者的数字花园.</p><p>这里系统整理了在学习浙江大学计算机科学与技术专业相关课程时积累的深度笔记、数学物理推导、软硬件工程代码、大作业研讨报告与期末复习手册。这些内容不是死记硬背的考前小抄，而是随着学习不断修正、重构与演进的终身知识库。</p><blockquote><p><strong>&quot;These notes are your treasure. Start your journey, keep thinking, and enjoy learning.&quot;</strong></p></blockquote><nav class="table-of-contents"><ul><li><a href="#培养路线阶梯-·-curriculum-roadmap">培养路线阶梯 · Curriculum Roadmap</a></li><li><a href="#核心科目专栏导航-·-courses">核心科目专栏导航 · Courses</a></li><li><a href="#研读自查清单-·-study-checklist">研读自查清单 · Study Checklist</a></li><li><a href="#治学心法-·-thinking-in-systems">治学心法 · Thinking In Systems</a></li><li><a href="#卷末寄语-·-final-remarks">卷末寄语 · Final Remarks</a></li></ul></nav><hr><h2 id="培养路线阶梯-·-curriculum-roadmap" tabindex="-1">培养路线阶梯 · Curriculum Roadmap <a class="header-anchor" href="#培养路线阶梯-·-curriculum-roadmap" aria-label="Permalink to &quot;培养路线阶梯 · Curriculum Roadmap&quot;">​</a></h2><p>计算机科学与自然科学体系是一座自底向上的精密大厦，推荐循序渐进研读：</p><div class="roadmap-step-grid"><div class="roadmap-step-card"><span class="step-phase-badge">阶段一 · 筑基思维</span><span class="step-title">程序设计与数理基石</span><span class="step-desc">建立严谨的结构化编程与指针内存模型，掌握离散逻辑形式化推导，通过普通物理学与力学导论筑牢唯象与自然科学世界观。</span><div class="step-tags"><span class="step-tag-pill">FPA · 算法基础</span><span class="step-tag-pill">DM · 离散数学</span><span class="step-tag-pill">PHY · 普通物理(力热)</span><span class="step-tag-pill">MECH · 力学导论</span></div></div><div class="roadmap-step-card"><span class="step-phase-badge">阶段二 · 核心基石</span><span class="step-title">硬件门电路与数据结构</span><span class="step-desc">自底向上理解卡诺图与有限状态机；掌握树、堆、图论与经典算法渐近复杂度分析；通过物理实验培养严谨的误差与数据处理直觉。</span><div class="step-tags"><span class="step-tag-pill">DLD · 数字逻辑</span><span class="step-tag-pill">FDS · 数据结构</span><span class="step-tag-pill">ALGO · 刷题实战</span><span class="step-tag-pill">PHY LAB · 物理实验</span></div></div><div class="roadmap-step-card"><span class="step-phase-badge">阶段三 · 软硬协同</span><span class="step-title">微体系结构与片上系统</span><span class="step-desc">深入单周期与五级流水线数据通路、Cache层次；通过 Vivado 与 FPGA 上板实现 IP2SOC 片上系统与硬件大作业。</span><div class="step-tags"><span class="step-tag-pill">CO · 计算机组成</span><span class="step-tag-pill">CO-MID · 备考手册</span><span class="step-tag-pill">IP2SOC · SoC实验</span><span class="step-tag-pill">Verilog · HDL基础</span></div></div><div class="roadmap-step-card"><span class="step-phase-badge">阶段四 · 高阶沉淀</span><span class="step-title">高阶算法、概率模型与通识</span><span class="step-desc">探索平衡树进阶、摊还分析与NP完全问题；夯实概率统计模型与电磁波动物理；结合大作业研讨与人文思政复习实现全面升华。</span><div class="step-tags"><span class="step-tag-pill">ADS · 高阶算法</span><span class="step-tag-pill">PMS · 概率统计(9章)</span><span class="step-tag-pill">PHY-II · 电磁与光学</span><span class="step-tag-pill">MARX · 马原</span><span class="step-tag-pill">SP · 形势与政策</span></div></div></div><hr><h2 id="核心科目专栏导航-·-courses" tabindex="-1">核心科目专栏导航 · Courses <a class="header-anchor" href="#核心科目专栏导航-·-courses" aria-label="Permalink to &quot;核心科目专栏导航 · Courses&quot;">​</a></h2><div class="garden-bento-grid"><a href="../Theory/Fundamentals_of_Programming.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">FPA</span><span class="bento-tag-badge core">编程基石</span></div><div class="bento-card-body"><div class="bento-icon-box">💻</div><div class="bento-content"><span class="bento-title">程序设计与算法基础</span><span class="bento-desc">程序设计思维、C/C++ 规范、指针与内存模型、高频算法题型分析</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">C/C++ 实战</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Digital_Logic_Design.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">DLD</span><span class="bento-tag-badge core">硬件逻辑</span></div><div class="bento-card-body"><div class="bento-icon-box">⚡</div><div class="bento-content"><span class="bento-title">数字逻辑设计</span><span class="bento-desc">数制系统、布尔代数、卡诺图化简、时序电路、有限状态机与 Verilog</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">状态机设计</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Fundamentals_of_Data_Structure.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">FDS</span><span class="bento-tag-badge core">算法核心</span></div><div class="bento-card-body"><div class="bento-icon-box">🌲</div><div class="bento-content"><span class="bento-title">数据结构基础</span><span class="bento-desc">线性表、树与森林、二叉平衡树、优先队列、图论算法与散列技术</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">84K字精研</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Discrete_Mathematics.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">DM</span><span class="bento-tag-badge math">数理形式化</span></div><div class="bento-card-body"><div class="bento-icon-box">📐</div><div class="bento-content"><span class="bento-title">离散数学</span><span class="bento-desc">命题谓词逻辑、集合与关系、等价偏序、图论定理、组合计数与生成函数</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">偏序/母函数</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Computer_Organization.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">CO</span><span class="bento-tag-badge core">体系架构</span></div><div class="bento-card-body"><div class="bento-icon-box">🖥️</div><div class="bento-content"><span class="bento-title">计算机组成与体系</span><span class="bento-desc">MIPS/RISC-V 架构、单周期数据通路、流水线冒险机制与 Cache 存储层次</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">流水线微架构</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Computer_Organization_Midterm.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">CO-MID</span><span class="bento-tag-badge core">备考速查</span></div><div class="bento-card-body"><div class="bento-icon-box">🎯</div><div class="bento-content"><span class="bento-title">计组期中主手册与速查卡</span><span class="bento-desc">265KB 逐章深入复习手册、单周期推导、流水线 Forwarding 旁路与考场速查卡</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">265KB完备主手册</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Advanced_Data_Structure_Algorithm_Analysis.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">ADS</span><span class="bento-tag-badge core">高阶算法</span></div><div class="bento-card-body"><div class="bento-icon-box">🚀</div><div class="bento-content"><span class="bento-title">高级数据结构与算法</span><span class="bento-desc">AVL 树、伸展树、B+ 树、左倾堆、红黑树、摊还分析与近似算法</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">260KB大扩充</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Probability_and_Mathematical_Statistics.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">PMS</span><span class="bento-tag-badge math">数理全章</span></div><div class="bento-card-body"><div class="bento-icon-box">🎲</div><div class="bento-content"><span class="bento-title">概率论与数理统计</span><span class="bento-desc">随机事件与概率、多维随机变量、极限定理、参数点估计与置信区间、假设检验推导</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">170KB 9章完备</span><span class="bento-arrow">→</span></div></a><a href="../Theory/General_Physics.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">PHY</span><span class="bento-tag-badge math">自然科学</span></div><div class="bento-card-body"><div class="bento-icon-box">🌌</div><div class="bento-content"><span class="bento-title">普通物理学（甲）I &amp; II</span><span class="bento-desc">经典力热基础、高斯与安培环路定理、麦克斯韦方程组、波动光学与近代物理</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">I &amp; II 全览</span><span class="bento-arrow">→</span></div></a><a href="../Lab/Physics-Lab.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">PHY LAB</span><span class="bento-tag-badge lab">实验全景</span></div><div class="bento-card-body"><div class="bento-icon-box">🔬</div><div class="bento-content"><span class="bento-title">普通物理学实验集 (14项)</span><span class="bento-desc">碰撞实验、磁滞回线、万用表设计、驻波、示波器、霍尔效应、北斗导航定位模拟</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">14个系列报告</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Marxism.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">MARX</span><span class="bento-tag-badge math">闭卷要点</span></div><div class="bento-card-body"><div class="bento-icon-box">🚩</div><div class="bento-content"><span class="bento-title">马克思主义基本原理</span><span class="bento-desc">唯物论辩证法、实践认识论、资本主义生产与剩余价值、考研核心考点</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">背诵导图</span><span class="bento-arrow">→</span></div></a><a href="../Theory/Situation_and_Policy.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">SP</span><span class="bento-tag-badge math">时事通识</span></div><div class="bento-card-body"><div class="bento-icon-box">📜</div><div class="bento-content"><span class="bento-title">形势与政策 I 复习精研</span><span class="bento-desc">时事热点专题深度解析、政策背景剖析与期末关键题干背诵资料合集</span></div></div></div><div class="bento-card-footer"><span class="bento-chip">66KB精研背诵</span><span class="bento-arrow">→</span></div></a></div><hr><h2 id="研读自查清单-·-study-checklist" tabindex="-1">研读自查清单 · Study Checklist <a class="header-anchor" href="#研读自查清单-·-study-checklist" aria-label="Permalink to &quot;研读自查清单 · Study Checklist&quot;">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 阅读课程核心概念与物理/数学直观</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 独立推导核心公式、定理证明与真值表</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 手算典型例题（如状态机化简、Dijkstra 每步过程、流水线冒险周期表）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> 定期总结易错点与极端边界条件（Corner Cases）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 尝试用自己的语言向他人解释某概念（费曼学习法）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> 期末复习时回顾错题与易混淆概念对比</label></li></ul><hr><h2 id="治学心法-·-thinking-in-systems" tabindex="-1">治学心法 · Thinking In Systems <a class="header-anchor" href="#治学心法-·-thinking-in-systems" aria-label="Permalink to &quot;治学心法 · Thinking In Systems&quot;">​</a></h2><p>学习计算机课程时，最宝贵的不是记住零散的最终结论，而是能自主解答这四个问题：</p><ol><li><strong>这个概念或硬件机制到底在解决什么核心痛点？</strong></li><li><strong>为什么前人要这样设计，而非采用更简单的方式？</strong></li><li><strong>它和系统上下层（编译器、硬件、操作系统）有什么联动？</strong></li><li><strong>换一种题目形式或工程场景后，我还能不能自己严密推出答案？</strong></li></ol><hr><h2 id="卷末寄语-·-final-remarks" tabindex="-1">卷末寄语 · Final Remarks <a class="header-anchor" href="#卷末寄语-·-final-remarks" aria-label="Permalink to &quot;卷末寄语 · Final Remarks&quot;">​</a></h2><p>最后，我想用 SGA 在 2026 年西决第七场不敌马刺的赛后采访中，他笑着说出的最后一句来作结，愿我们都能够：</p><div style="text-align:center;margin:2rem auto;font-size:1.35rem;font-weight:700;color:var(--wi-accent-dark);letter-spacing:2px;"> &quot;拿得起，也放得下。&quot; </div><div class="garden-quote-box" style="text-align:center;"><div class="garden-quote-title">🏀 SGA&#39;s Summer Whisper</div><div class="garden-quote-content" style="font-style:italic;font-family:Georgia, serif;font-size:1.15rem;"> &quot;Thanks, guys. You have a great summer. See you.&quot; </div><div style="text-align:right;margin-top:10px;font-weight:700;color:var(--wi-accent);"> -- Shai Gilgeous-Alexander ⚡ </div></div>',25)])])}const h=a(i,[["render",l]]);export{v as __pageData,h as default};
